  static String t(String lang, String key, {Map<String, String>? args}) {
    final normalizedLang = _normalizeLang(lang);
    final langMap = uiTranslations[normalizedLang] ?? uiTranslations['en']!;
    dynamic val = langMap[key];
    if (val == null) {
      final enMap = uiTranslations['en']!;
      val = enMap[key];
    }
    if (val == null) return key;

    if (val is List) {
      return val.join(', ');
    }

    String result = val.toString();
    if (args != null) {
      args.forEach((k, v) {
        result = result.replaceAll('{$k}', v);
      });
    }
    return result;
  }

  static List<String> translateList(String lang, String key) {
    final normalizedLang = _normalizeLang(lang);
    final langMap = uiTranslations[normalizedLang] ?? uiTranslations['en']!;
    final val = langMap[key];
    if (val is List) {
      return List<String>.from(val);
    }
    final enMap = uiTranslations['en']!;
    final enVal = enMap[key];
    if (enVal is List) {
      return List<String>.from(enVal);
    }
    return [];
  }

  static String _normalizeLang(String lang) {
    final l = lang.toLowerCase();
    if (l == 'zh-cn' || l == 'zh_cn') return 'zh-cn';
    if (l == 'ja-jp' || l == 'ja_jp') return 'ja-jp';
    return l;
  }
}
